update analysis_task
set status = #{running}, summary = #{summary}, update_by = #{username}, update_time = now()
where task_id = #{taskId} and status <> #{running}

update analysis_task
set summary = #{summary}, update_by = #{username}, update_time = now()
where task_id = #{taskId} and status = #{running}

update analysis_task
set summary = #{summary}, status = #{done}, update_by = #{username}, update_time = now()
where task_id = #{taskId}

update analysis_task
set status = #{failed}, summary = #{summary}, update_by = #{username}, update_time = now()
where task_id = #{taskId}

update ontology_datasource
set password_enc = #{passwordEnc}, update_by = #{username}, update_time = now()
where datasource_id = #{datasourceId}

mapper.select:
select proposal_name, config_json, task_id
from ontology_proposal
where proposal_id = #{proposalId}

select proposal_id, proposal_name, task_id, config_json
from ontology_proposal
where proposal_id = #{proposalId}

select t.task_id, t.summary, p.proposal_id, p.config_json
from analysis_task t
join ontology_proposal p on p.task_id = t.task_id and p.proposal_id = #{proposalId}
where t.task_id = #{taskId}

